export function contractForRoute(route: string): WimoorFeatureContract | undefined {
  return PAGE_FEATURE_CONTRACTS[route];
}

export function contractForKind(kind: string): WimoorFeatureContract | undefined {
  const route = KIND_TO_ROUTE[kind];
  return route ? PAGE_FEATURE_CONTRACTS[route] : undefined;
}
